#!/usr/bin/env bash
# southard2024_comprehensive_transcription — Perturbation Catalogue census (CRISPR screen / Perturb-seq)
# Paper: Comprehensive transcription factor perturbations recapitulate fibroblast transcriptional states
#        bioRxiv 2024 · doi:10.1101/2024.07.31.606073
#
# GENERATED by `igvfagent bench scaffold`. Review before trusting the
# numbers: variables marked TODO_VERIFY below were not resolvable from
# the paper's text and need a human to fill in.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
cd "$ROOT"
LABEL="southard2024_comprehensive_transcription"
IGVF=".venv/bin/igvfagent"

# MODALITY: from route default
MODALITY="${SOUTHARD2024_MODALITY:-crispr-screen}"

"$IGVF" perturb-catalog summary

"$IGVF" perturb-catalog search-modality --modality "$MODALITY" --dataset-limit 100

# Guide-library counts (10,979 guides; 1,836 TFs targeted), verified against
# the authors' own deposited guide x droplet UMI matrix (Zenodo
# 10.5281/zenodo.15200179) rather than trusted from the paper's prose.
python3 Benchmarks/southard2024_comprehensive_transcription/verify_guide_library.py

echo ""
echo "== southard2024_comprehensive_transcription benchmark complete =="
echo "Score with: .venv/bin/python Benchmarks/concordance.py --benchmark southard2024_comprehensive_transcription"
